template<int MODE, int T>
__device__ void body(const float* __restrict__ q, const float* __restrict__ k, const float* __restrict__ wq, const float* __restrict__ wk, float eps, float* qo, float* ko, int rows){
  // MODE 0 full, 1 load-only, 2 store-only, 3 empty
  if(MODE==3) return;
  uint64_t pl, ps;
  asm("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pl));
  asm("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(ps));
