#include <cuda_runtime.h>

// Per-head RMSNorm for Q and K. One row (128 fp32) per half-warp: 16 threads x 8 floats (256-bit access).
// Loads: L2::evict_first (read once). Stores: L2::evict_last, so this call's outputs are preferred over the
// flush's dirty lines when the L2 picks victims. Both hints apply only to this call's own buffers.
// One-shot grid of small CTAs (31 regs, 16 CTAs/SM): beat persistent loops on every size in probes.

struct f8 { float v[8]; };

__device__ __forceinline__ f8 ld_x(const float* p) {
    f8 r;
    asm volatile("ld.global.nc.L1::no_allocate.L2::evict_first.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(r.v[0]), "=f"(r.v[1]), "=f"(r.v[2]), "=f"(r.v[3]),
                   "=f"(r.v[4]), "=f"(r.v[5]), "=f"(r.v[6]), "=f"(r.v[7])
                 : "l"(p));
    return r;
}

__device__ __forceinline__ f8 ld_w(const float* p) {
    f8 r;
    asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(r.v[0]), "=f"(r.v[1]), "=f"(r.v[2]), "=f"(r.v[3]),
                   "=f"(r.v[4]), "=f"(r.v[5]), "=f"(r.v[6]), "=f"(r.v[7])
                 : "l"(p));
    return r;
}

__device__ __forceinline__ void st_y(float* p, const f8& r) {
    asm volatile("st.global.L2::evict_last.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};"
                 :: "l"(p), "f"(r.v[0]), "f"(r.v[1]), "f"(r.v[2]), "f"(r.v[3]),
                    "f"(r.v[4]), "f"(r.v[5]), "f"(r.v[6]), "f"(r.v[7])
                 : "memory");
}

constexpr int THREADS = 128;
constexpr int ROWS_PER_CTA = THREADS / 16;

// INTERLEAVE: even CTAs take Q rows, odd CTAs the matching K rows (better at small sizes);
// otherwise CTAs walk all Q rows then all K rows.
template <bool INTERLEAVE>
__global__ void __launch_bounds__(THREADS)
qk_rmsnorm_kernel(const float* __restrict__ q, const float* __restrict__ k,
                  const float* __restrict__ wq, const float* __restrict__ wk, float eps,
                  float* __restrict__ qo, float* __restrict__ ko, int rows) {
    const int l = threadIdx.x & 15;
    const int h = threadIdx.x >> 4;
    bool isq;
    int r;
    if (INTERLEAVE) {
        isq = (blockIdx.x & 1) == 0;
        r = (blockIdx.x >> 1) * ROWS_PER_CTA + h;
        if (r >= rows) return;
    } else {
        const int g = blockIdx.x * ROWS_PER_CTA + h;
        if (g >= 2 * rows) return;
        isq = g < rows;
        r = isq ? g : g - rows;
    }
    const f8 x = ld_x((isq ? q : k) + (long)r * 128 + l * 8);
    const f8 w = ld_w((isq ? wq : wk) + (r % 48) * 128 + l * 8);
    float s = 0.f;
#pragma unroll
    for (int j = 0; j < 8; j++) s = fmaf(x.v[j], x.v[j], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.f / 128.f) + eps);
    f8 y;
#pragma unroll
    for (int j = 0; j < 8; j++) y.v[j] = x.v[j] * inv * w.v[j];
    st_y((isq ? qo : ko) + (long)r * 128 + l * 8, y);
}

// rows = B*S*48 rows per tensor (always a multiple of 48, so of ROWS_PER_CTA).
extern "C" void launch_qk_rmsnorm(const float* q, const float* k, const float* wq, const float* wk,
                                  float eps, float* qo, float* ko, int rows, cudaStream_t stream) {
    if (rows <= 0) return;
    const int per_tensor = (rows + ROWS_PER_CTA - 1) / ROWS_PER_CTA;
    if (rows <= 256 * 48) {
        qk_rmsnorm_kernel<true><<<2 * per_tensor, THREADS, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
    } else {
        const int grid = (2 * rows + ROWS_PER_CTA - 1) / ROWS_PER_CTA;
        qk_rmsnorm_kernel<false><<<grid, THREADS, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
    }
}

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <ATen/cuda/CUDAContext.h>

extern "C" void launch_qk_rmsnorm(const float* q, const float* k, const float* wq, const float* wk,
                                  float eps, float* qo, float* ko, int rows, cudaStream_t stream);

void run(torch::Tensor query, torch::Tensor key, torch::Tensor weight_q, torch::Tensor weight_k,
         double eps, torch::Tensor query_norm, torch::Tensor key_norm) {
    TORCH_CHECK(query.is_cuda() && query.scalar_type() == torch::kFloat32 && query.is_contiguous());
    TORCH_CHECK(key.is_contiguous() && query_norm.is_contiguous() && key_norm.is_contiguous());
    TORCH_CHECK(query.size(-1) == 128 && query.size(-2) == 48);
    TORCH_CHECK(weight_q.is_contiguous() && weight_k.is_contiguous());
    const c10::cuda::CUDAGuard guard(query.device());
    const int rows = (int)(query.numel() / 128);
    launch_qk_rmsnorm(query.data_ptr<float>(), key.data_ptr<float>(), weight_q.data_ptr<float>(),
                      weight_k.data_ptr<float>(), (float)eps, query_norm.data_ptr<float>(),
                      key_norm.data_ptr<float>(), rows, at::cuda::getCurrentCUDAStream());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "per-head RMSNorm of Q and K"); }

#include <cuda_runtime.h>
#include <stdint.h>

struct f8 { float v[8]; };

__device__ __forceinline__ f8 ld_x(const float* p) {
    f8 r;
    asm volatile("ld.global.nc.L1::no_allocate.L2::evict_first.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(r.v[0]), "=f"(r.v[1]), "=f"(r.v[2]), "=f"(r.v[3]),
                   "=f"(r.v[4]), "=f"(r.v[5]), "=f"(r.v[6]), "=f"(r.v[7])
                 : "l"(p));
    return r;
}

__device__ __forceinline__ f8 ld_w(const float* p) {
    f8 r;
    asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(r.v[0]), "=f"(r.v[1]), "=f"(r.v[2]), "=f"(r.v[3]),
                   "=f"(r.v[4]), "=f"(r.v[5]), "=f"(r.v[6]), "=f"(r.v[7])
                 : "l"(p));
    return r;
}

__device__ __forceinline__ void st_y(float* p, const f8& r) {
    asm volatile("st.global.L2::evict_last.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};"
                 :: "l"(p), "f"(r.v[0]), "f"(r.v[1]), "f"(r.v[2]), "f"(r.v[3]),
                    "f"(r.v[4]), "f"(r.v[5]), "f"(r.v[6]), "f"(r.v[7])
                 : "memory");
}

__device__ __forceinline__ void norm_store(const f8& x, const f8& w, float eps, float* dst) {
    float s = 0.f;
#pragma unroll
    for (int j = 0; j < 8; j++) s = fmaf(x.v[j], x.v[j], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.f / 128.f) + eps);
    f8 y;
#pragma unroll
    for (int j = 0; j < 8; j++) y.v[j] = x.v[j] * inv * w.v[j];
    st_y(dst, y);
}

template <int T, bool INTERLEAVE>
__global__ void __launch_bounds__(T)
direct_kernel(const float* __restrict__ q, const float* __restrict__ k,
              const float* __restrict__ wq, const float* __restrict__ wk, float eps,
              float* __restrict__ qo, float* __restrict__ ko, int rows) {
    constexpr int RPC = T / 16;
    const int l = threadIdx.x & 15;
    const int h = threadIdx.x >> 4;
    bool isq;
    int r;
    if (INTERLEAVE) {
        isq = (blockIdx.x & 1) == 0;
        r = (blockIdx.x >> 1) * RPC + h;
        if (r >= rows) return;
    } else {
        const int g = blockIdx.x * RPC + h;
        if (g >= 2 * rows) return;
        isq = g < rows;
        r = isq ? g : g - rows;
    }
    const f8 x = ld_x((isq ? q : k) + (long)r * 128 + l * 8);
    const f8 w = ld_w((isq ? wq : wk) + (r % 48) * 128 + l * 8);
    norm_store(x, w, eps, (isq ? qo : ko) + (long)r * 128 + l * 8);
}

// 1-D bulk copy of the CTA's T/16 contiguous rows into shared memory, one mbarrier.
template <int T>
__global__ void __launch_bounds__(T)
bulk_kernel(const float* __restrict__ q, const float* __restrict__ k,
            const float* __restrict__ wq, const float* __restrict__ wk, float eps,
            float* __restrict__ qo, float* __restrict__ ko, int rows) {
    constexpr int RPC = T / 16;
    constexpr unsigned BYTES = RPC * 512;
    __shared__ __align__(128) float tile[RPC * 128];
    __shared__ __align__(8) uint64_t bar;
    const int l = threadIdx.x & 15;
    const int h = threadIdx.x >> 4;
    const int g0 = blockIdx.x * RPC;
    const bool isq = g0 < rows;
    const int r0 = isq ? g0 : g0 - rows;
    const unsigned bar_a = (unsigned)__cvta_generic_to_shared(&bar);
    const unsigned tile_a = (unsigned)__cvta_generic_to_shared(tile);
    if (threadIdx.x == 0) {
        const float* src = (isq ? q : k) + (long)r0 * 128;
        uint64_t pol;
        asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
        asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" :: "r"(bar_a));
        asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
        asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" :: "r"(bar_a), "r"(BYTES) : "memory");
        asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1], %2, [%3], %4;"
                     :: "r"(tile_a), "l"(src), "r"(BYTES), "r"(bar_a), "l"(pol) : "memory");
    }
    const int r = r0 + h;
    const f8 w = ld_w((isq ? wq : wk) + (r % 48) * 128 + l * 8);
    __syncthreads();
    asm volatile("{\n\t.reg .pred p;\n\tWAIT_%=:\n\t"
                 "mbarrier.try_wait.parity.shared::cta.b64 p, [%0], 0;\n\t"
                 "@!p bra WAIT_%=;\n\t}" :: "r"(bar_a) : "memory");
    f8 x;
    const float4* t4 = reinterpret_cast<const float4*>(tile + h * 128 + l * 8);
    const float4 a = t4[0], b = t4[1];
    x.v[0] = a.x; x.v[1] = a.y; x.v[2] = a.z; x.v[3] = a.w;
    x.v[4] = b.x; x.v[5] = b.y; x.v[6] = b.z; x.v[7] = b.w;
    norm_store(x, w, eps, (isq ? qo : ko) + (long)r * 128 + l * 8);
}

// variant: 0 control (T=128, interleave for small rows), 1 direct T=1024, 2 direct T=512,
// 3 bulk T=256, 4 direct T=256
extern "C" void launch_qk_rmsnorm(const float* q, const float* k, const float* wq, const float* wk,
                                  float eps, float* qo, float* ko, int rows, int variant, cudaStream_t stream) {
    if (rows <= 0) return;
    switch (variant) {
    case 1: direct_kernel<1024, false><<<(2 * rows + 63) / 64, 1024, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    case 2: direct_kernel<512, false><<<(2 * rows + 31) / 32, 512, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    case 3: bulk_kernel<256><<<2 * rows / 16, 256, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    case 4: direct_kernel<256, false><<<(2 * rows + 15) / 16, 256, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    default:
        if (rows <= 256 * 48)
            direct_kernel<128, true><<<2 * ((rows + 7) / 8), 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
        else
            direct_kernel<128, false><<<(2 * rows + 7) / 8, 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
    }
}

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <ATen/cuda/CUDAContext.h>

extern "C" void launch_qk_rmsnorm(const float* q, const float* k, const float* wq, const float* wk,
                                  float eps, float* qo, float* ko, int rows, int variant, cudaStream_t stream);

static int pick_variant(int64_t B, int64_t S) {
    if (B == 1 && S == 128) return 1;
    if (B == 2 && S == 128) return 2;
    if (B == 1 && S == 256) return 3;
    if (B == 2 && S == 293) return 3;
    if (B == 8 && S == 128) return 4;
    if (B == 4 && S == 256) return 3;
    if (B == 4 && S == 512) return 3;
    if (B == 16 && S == 256) return 3;
    if (B == 32 && S == 128) return 4;
    return 0;
}

void run(torch::Tensor query, torch::Tensor key, torch::Tensor weight_q, torch::Tensor weight_k,
         double eps, torch::Tensor query_norm, torch::Tensor key_norm) {
    TORCH_CHECK(query.is_cuda() && query.scalar_type() == torch::kFloat32 && query.is_contiguous());
    TORCH_CHECK(key.is_contiguous() && query_norm.is_contiguous() && key_norm.is_contiguous());
    TORCH_CHECK(query.size(-1) == 128 && query.size(-2) == 48);
    TORCH_CHECK(weight_q.is_contiguous() && weight_k.is_contiguous());
    const c10::cuda::CUDAGuard guard(query.device());
    const int rows = (int)(query.numel() / 128);
    const int variant = pick_variant(query.size(0), query.size(1));
    launch_qk_rmsnorm(query.data_ptr<float>(), key.data_ptr<float>(), weight_q.data_ptr<float>(),
                      weight_k.data_ptr<float>(), (float)eps, query_norm.data_ptr<float>(),
                      key_norm.data_ptr<float>(), rows, variant, at::cuda::getCurrentCUDAStream());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "per-head RMSNorm of Q and K"); }

