__device__ __forceinline__ void norm_store(const f8& x, const f8& w, float eps, float* dst) {
    float s = 0.f;
#pragma unroll
    for (int j = 0; j < 8; j++) s = fmaf(x.v[j], x.v[j], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.f / 128.f) + eps);
    f8 y;
#pragma unroll
    for (int j = 0; j < 8; j++) y.v[j] = x.v[j] * inv * w.v[j];
    st_y(dst, y);
}

// One row per half-warp, 8 rows per 128-thread CTA. PREFETCH: CTAs in the first half of the grid also
// prefetch (to L2) the 4 KB chunk of the CTA G/2 later, so late-dispatched CTAs find their rows requested.
template <bool INTERLEAVE, bool PREFETCH>
__global__ void __launch_bounds__(128)
row_kernel(const float* __restrict__ q, const float* __restrict__ k,
           const float* __restrict__ wq, const float* __restrict__ wk, float eps,
           float* __restrict__ qo, float* __restrict__ ko, int rows) {
    const int l = threadIdx.x & 15;
    const int h = threadIdx.x >> 4;
    bool isq;
    int r;
    if (INTERLEAVE) {
        isq = (blockIdx.x & 1) == 0;
        r = (blockIdx.x >> 1) * 8 + h;
    } else {
        const int g = blockIdx.x * 8 + h;
        isq = g < rows;
        r = isq ? g : g - rows;
    }
    const f8 x = ld_x((isq ? q : k) + (long)r * 128 + l * 8);
    if (PREFETCH && threadIdx.x == 0 && (int)blockIdx.x < (int)gridDim.x / 2) {
        const int g2 = (blockIdx.x + gridDim.x / 2) * 8;
        const float* p2 = g2 < rows ? q + (long)g2 * 128 : k + (long)(g2 - rows) * 128;
        asm volatile("cp.async.bulk.prefetch.L2.global [%0], 4096;" :: "l"(p2) : "memory");
    }
    const f8 w = ld_w((isq ? wq : wk) + (r % 48) * 128 + l * 8);
    norm_store(x, w, eps, (isq ? qo : ko) + (long)r * 128 + l * 8);
}

// Two rows per half-warp (16 rows = 8 KB contiguous per CTA), both loads issued first; capped at 40 regs
// so 12 CTAs/SM fit and 24,576-row workloads run in one wave (1536 CTAs <= 1776 slots).
__global__ void __launch_bounds__(128, 12)
row2_kernel(const float* __restrict__ q, const float* __restrict__ k,
            const float* __restrict__ wq, const float* __restrict__ wk, float eps,
            float* __restrict__ qo, float* __restrict__ ko, int rows) {
    const int l = threadIdx.x & 15;
    const int h = threadIdx.x >> 4;
    const int g = blockIdx.x * 16 + h;
    const bool isq = g < rows;  // rows % 16 == 0: a CTA never straddles Q and K
    const int r = isq ? g : g - rows;
    const float* src = (isq ? q : k) + (long)r * 128 + l * 8;
    const f8 x0 = ld_x(src);
    const f8 x1 = ld_x(src + 8 * 128);
    const float* wb = isq ? wq : wk;
    const f8 w0 = ld_w(wb + (r % 48) * 128 + l * 8);
    const f8 w1 = ld_w(wb + ((r + 8) % 48) * 128 + l * 8);
    float* dst = (isq ? qo : ko) + (long)r * 128 + l * 8;
    norm_store(x0, w0, eps, dst);
    norm_store(x1, w1, eps, dst + 8 * 128);
}

// variant: 0 control, 1 prefetch (interleaved), 2 row2
extern "C" void launch_qk_rmsnorm(const float* q, const float* k, const float* wq, const float* wk,
                                  float eps, float* qo, float* ko, int rows, int variant, cudaStream_t stream) {
    if (rows <= 0) return;
    const int g1 = 2 * rows / 8;
    switch (variant) {
    case 1: row_kernel<false, true><<<g1, 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    case 2: row2_kernel<<<2 * rows / 16, 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows); break;
    default:
        if (rows <= 256 * 48)
            row_kernel<true, false><<<g1, 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
        else
            row_kernel<false, false><<<g1, 128, 0, stream>>>(q, k, wq, wk, eps, qo, ko, rows);
    }
}

